export const BODY: string = "\n<p>بعض النماذج الإلكترونية صارمة جدًا. تطلب صورة أصغر من 50 كيلوبايت وترفض كل ما هو أكبر، مهما كانت الصورة جميلة.</p>\n<p>يبدو هذا الحد صغيرًا جدًا إذا قارنته بصورة هاتف حديث. صورة واحدة قد تزن 4 ميغابايت أو أكثر، أي ثمانين ضعف الحد المطلوب.</p>\n<p>في هذا الدليل نشرح كيف تضغط صورة إلى 50 كيلوبايت بالطريقة الصحيحة. ستعرف ماذا يعني هذا الحد، وأي الصيغ تتحمله أفضل، وكيف تصل إليه دون أن تتحول صورتك إلى بقعة ضبابية.</p>\n<h2 id=\"what-does-50kb-mean\">ماذا يعني 50 كيلوبايت فعلًا؟</h2>\n<p>الكيلوبايت وحدة لقياس حجم الملف. خمسون كيلوبايت تساوي نحو 51,200 بايت، وهي كمية بيانات صغيرة جدًا بمعايير اليوم.</p>\n<p>للمقارنة، صورة الهاتف المعتادة تزن بين 2 و6 ميغابايت. هذا يعني أنك تحتاج غالبًا إلى إزالة أكثر من 98 بالمئة من وزن الملف الأصلي.</p>\n<h2 id=\"why-portals-ask-for-50kb\">لماذا تطلب البوابات الإلكترونية 50 كيلوبايت؟</h2>\n<p>نماذج الحكومة ولوحات الامتحانات وبوابات التوظيف تخزّن ملايين الملفات المرفوعة. الملفات الصغيرة تُبقي قواعد بياناتها سريعة وفواتير التخزين منخفضة.</p>\n<p>بوابة جواز السفر لا تحتاج صورة شخصية بدقة 12 ميغابكسل. تحتاج وجهًا واضحًا وأبعادًا صحيحة وملفًا يستطيع نظامها معالجته في أجزاء من الثانية.</p>\n<h2 id=\"how-compression-reaches-50kb\">كيف يصل الضغط إلى 50 كيلوبايت؟</h2>\n<p>الضغط يزيل بيانات لا تلاحظها العين تقريبًا. يُنعّم التدرجات اللونية الدقيقة ويزيل الضجيج الخفيف ويُبسّط التفاصيل المزدحمة.</p>\n<p>عندما لا تكفي الجودة وحدها، تُقلّل الأداة أبعاد الصورة بالبكسل. الصورة الأصغر تحتاج ببساطة بيانات أقل لوصف نفسها.</p>\n<h2 id=\"binary-quality-search\">البحث الثنائي عن الجودة، شرح مبسّط</h2>\n<p>أداة 50 كيلوبايت في CompressMyPic لا تُخمّن رقم الجودة. بل تُجري بحثًا ثنائيًا: تختبر مستويات الجودة حتى تجد الأعلى الذي ما زال يناسب الحد.</p>\n<p>فكّر فيها كأنك تُخمّن رقمًا بين 1 و100. كل اختبار يقلّص النطاق المتبقي إلى النصف، فيصل إلى النتيجة بسرعة.</p>\n<h2 id=\"best-format-for-50kb\">ما أفضل صيغة عند 50 كيلوبايت؟</h2>\n<p>لصور الأشخاص، تكون JPG غالبًا الخيار الأفضل عند 50 كيلوبايت. تتعامل مع درجات لون البشرة الناعمة والتدرجات أفضل بكثير من PNG عند هذه الأحجام الصغيرة.</p>\n<p>أما PNG فهو الخيار الخاطئ لمعظم الصور بهذا الحجم. يحفظ الصور دون فقدان، لذلك قد تبقى الصورة المفصّلة أكبر بكثير من 50 كيلوبايت حتى بأبعاد صغيرة.</p>\n<h2 id=\"quality-at-50kb\">ما الجودة التي تتوقعها عند 50 كيلوبايت؟</h2>\n<p>لنكن صادقين: 50 كيلوبايت حل وسط. الوجه سيبقى مميزًا والمستند سيبقى مقروءًا، لكن التفاصيل الدقيقة ستفقد بعض حدّتها.</p>\n<p>الصور الشخصية تتحمل الحد أفضل لأن الوجوه فيها مساحات ناعمة. الشعر والقماش يفقدان بعض النسيج، لكن الصورة ككل تبقى نظيفة.</p>\n<h2 id=\"common-uses-for-50kb\">أين تُستخدم صورة 50 كيلوبايت فعلًا؟</h2>\n<p>طلبات جواز السفر والتأشيرات هي الحالة الكلاسيكية. كثير من البوابات تحدد الصورة بـ50 كيلوبايت وتطلب أيضًا أبعادًا دقيقة بالبكسل.</p>\n<p>نماذج التسجيل للامتحانات تستخدم الحد نفسه للصورة والتوقيع. التوقيع الممسوح ضوئيًا معظمه مساحة بيضاء، لذلك يُضغط بسهولة كبيرة.</p>\n<h2 id=\"how-to-use-the-tool\">كيفية استخدام أداة ضغط الصورة إلى 50 كيلوبايت</h2>\n<p>افتح <a href=\"/ar/daght-as-sura-ila-50kb/\">أداة ضغط الصورة إلى 50 كيلوبايت</a> في متصفحك. كل شيء يعمل على جهازك، فصورتك لا تُرفع إلى أي خادم أبدًا.</p>\n<p>أسقط صورتك في منطقة الرفع. تُقبل ملفات JPG وPNG وWebP وHEIC، بحجم إدخال يصل إلى 25 ميغابايت.</p>\n<ol>\n<li>ارفع صورتك إلى أداة 50 كيلوبايت.</li>\n<li>دع البحث الثنائي يجد أفضل جودة تناسب الحد.</li>\n<li>عاين النتيجة وافحص الوجوه والنص عن قرب.</li>\n<li>نزّل الملف وارفعه إلى البوابة.</li>\n</ol>\n<h2 id=\"mistakes-to-avoid\">أخطاء تجعل 50 كيلوبايت أصعب مما يجب</h2>\n<p>أكثر الأخطاء شيوعًا أن تبدأ من لقطة شاشة بدل الصورة الأصلية. لقطات الشاشة تضيف ضجيجًا يهدر كيلوبايتات ثمينة.</p>\n<p>خطأ آخر أن تثبّت الصيغة على PNG لصورة فوتوغرافية. PNG لا يستطيع التخلص من وزن كافٍ، وستحذرك الأداة من عدم الوصول إلى الهدف.</p>\n<h2 id=\"50kb-vs-other-sizes\">50 كيلوبايت مقابل 100 و200 كيلوبايت: مقارنة سريعة</h2>\n<p>عند 100 كيلوبايت، تحتفظ الصورة الشخصية بتفاصيل أوضح بكثير من 50 كيلوبايت. الشعر والنظارات وحواف القماش تبدو أنظف.</p>\n<p>إذا كانت بوابتك تقبل 100 كيلوبايت، فلا تضغط إلى 50 كيلوبايت دون سبب. اقرأ مقارنتنا في <a href=\"/ar/blog/hajm-as-sura-50kb-vs-100kb-vs-200kb/\">50 كيلوبايت مقابل 100 كيلوبايت مقابل 200 كيلوبايت: أي حجم تختار؟</a> قبل أن تقرر.</p>\n<h2 id=\"privacy-and-safety\">الخصوصية: ماذا يحدث لصورتك؟</h2>\n<p>الضغط يحدث بالكامل في متصفحك. صورة هويتك لا تنتقل أبدًا إلى خادم، وهذا مهم عندما يكون الملف صورة جواز سفر.</p>\n<p>الأداة تزيل أيضًا بيانات الموقع المخفية من صورتك. وسوم GPS من الكاميرا تُحذف أثناء الضغط، فلا يحمل الملف المنزّل أي سجل لمكان التقاطه.</p>\n<h2 id=\"exam-forms-at-50kb\">50 كيلوبايت لنماذج الامتحانات والقبول</h2>\n<p>لوحات الامتحانات من أشد مستخدمي حد 50 كيلوبايت. تطلب صورة وتوقيعًا، وكلاهما أقل من 50 كيلوبايت وبصيغة محددة.</p>\n<p>قواعد الصورة عادة هي النصف الأصعب. يجب أن يكون الوجه مواجهًا للأمام والخلفية بسيطة والأبعاد دقيقة، وغالبًا 200 في 230 بكسل أو ما شابه.</p>\n<h2 id=\"crop-before-compressing\">قصّ الصورة أولًا، ثم اضغطها</h2>\n<p>القص قبل الضغط هو أنجع حيلة للجودة عند 50 كيلوبايت. كل بكسل تزيله هو بيانات لم يعد الضاغط بحاجة إلى حفظها.</p>\n<p>لصورة شخصية، قصّ حتى الرأس والكتفين. الوجه يحصل على حصة أكبر من ميزانية 50 كيلوبايت، فيبقى أوضح.</p>\n<h2 id=\"under-50kb-badge\">فهم شارة «أقل من 50 كيلوبايت»</h2>\n<p>عندما تنتهي الأداة، تعرض شارة «أقل من 50 كيلوبايت» على النتائج الناجحة. هذه الشارة هي تأكيدك بأن الملف قد تجاوز الحد.</p>\n<p>ثق بالشارة أكثر من قراءة جهازك. الأنظمة المختلفة تُقرّب أحجام الملفات بشكل مختلف، بينما تقيس الأداة عدد البايتات بدقة.</p>\n<h2 id=\"when-50kb-is-impossible\">متى يكون 50 كيلوبايت مستحيلًا فعلًا؟</h2>\n<p>بعض الصور لا تستطيع الوصول إلى 50 كيلوبايت دون أن تصبح عديمة الفائدة. صورة جماعية مزدحمة بعشرين وجهًا مثال على ذلك.</p>\n<p>الأبعاد الثابتة تجعل الأمر أصعب. إذا طلبت البوابة حجمًا كبيرًا بالبكسل مع حد 50 كيلوبايت، فقد تتعارض القاعدتان معًا.</p>\n<h2 id=\"storing-compressed-files\">حفظ الملفات المضغوطة وإعادة استخدامها</h2>\n<p>احتفظ بملفاتك المضغوطة منظمة. مجلد باسم الطلب، وبداخله الصورة والتوقيع، يجنّبك الارتباك لاحقًا.</p>\n<p>لا تحذف الملفات الأصلية. البوابات تغيّر قواعدها، وملف 50 كيلوبايت لا يمكن تحويله مجددًا إلى نسخة أصلية عالية الجودة.</p>\n<h2 id=\"lighting-and-source-quality\">الإضاءة وجودة المصدر أهم من الإعدادات</h2>\n<p>لا يستطيع أي ضاغط إنقاذ صورة مصدر سيئة. الصورة الشخصية المظلمة والمشوشة ستبقى مظلمة ومشوشة عند 50 كيلوبايت، فقط بحجم أصغر.</p>\n<p>الإضاءة الجيدة هي أرخص تحسين للجودة. صورة ملتقطة قرب نافذة تتفوق على صورة تحت مصباح أصفر، مهما كان حجم الملف.</p>\n<h2 id=\"backgrounds-and-clothing\">الخلفيات والملابس والتباين</h2>\n<p>الخلفية البسيطة تُضغط أفضل بكثير من الخلفية المزدحمة. كل ورقة شجرة أو ملصق أو نقش في الخلفية يكلّف كيلوبايتات كان الوجه أولى بها.</p>\n<p>قف أمام جدار فاتح فارغ لصور الهوية. المنطقة البسيطة تُضغط إلى لا شيء تقريبًا، تاركة الميزانية للوجه.</p>\n<h2 id=\"retaking-vs-fixing\">متى تلتقط صورة جديدة بدل إعادة الضغط</h2>\n<p>أحيانًا يكون الحل الأسرع صورة جديدة لا إعدادًا جديدًا. إذا كان المصدر ضبابيًا أو مظلمًا أو سيئ التأطير، فلن ينقذه الضغط.</p>\n<p>إذا احتجت حدًا مختلفًا لنموذج آخر، جرّب <a href=\"/ar/daght-as-sura-ila-100kb/\">ضاغط 100 كيلوبايت</a> أو <a href=\"/ar/daght-as-sura-ila-200kb/\">ضاغط 200 كيلوبايت</a> أو <a href=\"/ar/daght-as-sura-ila-hajm-muayyan/\">ضاغط حجم الملف المستهدف</a> لحجم مخصص دقيق. وللنسخة خطوة بخطوة من هذه العملية، اقرأ <a href=\"/ar/blog/kayfiyya-daght-as-sura-ila-50kb/\">كيفية ضغط صورة إلى 50 كيلوبايت</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"هل صورة 50 كيلوبايت كافية لطلب جواز السفر؟","answer":"نعم، عندما تحدد البوابة نفسها حد 50 كيلوبايت. البوابات التي تطلب هذا الحد مصممة لقراءة الصور بهذا الحجم، وملف JPG مضغوط جيدًا يُبقي الوجه واضحًا. تأكد أيضًا من أن أبعاد البكسل تطابق قواعد البوابة، لأن الحجم والأبعاد يُفحصان بشكل منفصل."},{"question":"لماذا تبدو صورتي ناعمة بعد ضغطها إلى 50 كيلوبايت؟","answer":"النعومة تأتي من إزالة البيانات الكبيرة اللازمة للوصول إلى هذا الحجم الصغير. البدء من الصورة الأصلية عالية الجودة يساعد، وكذلك إبقاء الأبعاد كبيرة بقدر ما يسمح الحد. تجنب إعادة ضغط نسخة مضغوطة أصلًا، لأن كل جولة تضيف نعومة أكثر."},{"question":"هل يمكنني ضغط صورة إلى 50 كيلوبايت على هاتفي؟","answer":"نعم. الأداة تعمل في متصفح الهواتف والأجهزة اللوحية، والضغط يحدث على جهازك. ارفع الصورة من معرضك، وانتظر النتيجة، وعاينها، ثم نزّل النسخة المضغوطة."},{"question":"ماذا أفعل إذا لم تنزل صورتي إلى أقل من 50 كيلوبايت؟","answer":"غيّر صيغة الإخراج إلى JPG أو WebP، لأن PNG نادرًا ما يناسب الصور عند 50 كيلوبايت. اسمح بتقليص الأبعاد حتى تستطيع الأداة خفض حجم البكسل. وإذا طلبت البوابة أيضًا أبعادًا ثابتة، جرّب WebP أولًا ثم JPG مع قص أصغر من المصدر."},{"question":"هل يغيّر الضغط إلى 50 كيلوبايت أبعاد البكسل؟","answer":"ليس دائمًا. تحاول الأداة أولًا الوصول إلى 50 كيلوبايت بخفض الجودة بالحجم الكامل. ولا تقلّل الأبعاد إلا عندما لا تكفي الجودة وحدها للوصول إلى الهدف. وإذا احتاجت بوابتك أبعادًا دقيقة، فتحقق من أبعاد النتيجة قبل الرفع."},{"question":"هل من الآمن ضغط صورة جواز سفر في أداة متصفح؟","answer":"مع هذه الأداة، نعم، لأن كل المعالجة تتم محليًا في متصفحك ولا يُرفع شيء إلى خادم. كما تزيل الأداة وسوم موقع GPS أثناء الضغط. تجنب الأدوات التي تطلب رفع صور الهوية إلى خادم مجهول."}];
